import collections
import logging
import signal
from ute_ue.exceptions import UeCommunicationError
from ute_common_abstract_core import logger as core_logging
from . import pc_server_exceptions
from .heartbeat import Heartbeat
from .server_base import PcServer
from .server_commands import TEST, QXDM, THROUGHPUT, MBMS_SESSION

try:
    import zmq
except ImportError:
    logging.getLogger('ute_ue').warning("ZMQ library not found, please install it using 'pip install pyzmq'")

SOCKET = collections.namedtuple("SOCKET", "socket dictionary")


class QxdmUePcHandler(PcServer):
    """Qxdm Ue Pc Handler class represents object which connects to UePcServer allowing to control Ue from remote machine."""

    def __init__(self):
        """
        Qxdm Ue Pc Handler

        :return:                    None
        :rtype:                     None
        """
        super(QxdmUePcHandler, self).__init__()
        signal.signal(signal.SIGUSR1, self._socket_setup_fail)
        signal.signal(signal.SIGUSR2, self._heartbeat_timer_exceeded)
        signal.signal(signal.SIGINT, self._user_stop)
        self._SOCKET_COMMAND_INPUT = None
        self._SOCKET_QXDM_MESSAGES = None
        self._SOCKET_COMMAND_OUTPUT = None
        self._SOCKET_HEARTBEAT = None

        self.timeout_overwrite_dictionary = {
            QXDM.CONFIG: 360,
            QXDM.STOP: 0,
            QXDM.REBOOT: 360,
            QXDM.ATTACH: 0,
            QXDM.DETACH: 0,
            QXDM.GET_LOG_ITEM: 0,
            QXDM.GET_LOG_ITEMS: -1,
            QXDM.CLEAR_CURRENT_LOG_ITEMS: 0,
            QXDM.SAVE_ISF: 180,
            QXDM.COPY_LOGS: -1,
            QXDM.CLEAR_ALL_LOGS: 0,
            QXDM.GET_MEASUREMENT: -1,
            QXDM.READ_NV_ITEM: 120,
            QXDM.WRITE_NV_ITEM: 120,

            THROUGHPUT.START: 120,
            THROUGHPUT.STOP: 60,
            THROUGHPUT.GET_STATISTICS: 0,
            THROUGHPUT.RESET_STATISTICS: 0,

            MBMS_SESSION.STOP_VERIFYING: 40,

            TEST.START: 600,
            TEST.FINISHED: 30,
            TEST.RECOVERY: 0,
            TEST.RESET_TEST_ENVIRONMENT: 30,
            TEST.COPY_SERVER_LOGS: 60,
            TEST.GET_SERVER_VERSION: 40,
            TEST.CHECK_SERIAL: 40,
            TEST.CHECK_COM_PORT: 40,
        }

        self.special_outputs = {}
        self.enable_heartbeat = True
        self.ue_pc_host = None
        self.logger = None

    def _socket_setup_fail(self, signum, frame):
        self.logger.warning("Failed to setup [HEARTBEAT] socket to [UE PC]")
        self.failed = True
        raise UeCommunicationError("Failed to setup [HEARTBEAT] socket to [UE PC]")

    def _heartbeat_timer_exceeded(self, signum, frame):
        self.logger.warning("[HEARTBEAT] failed to reach [UE PC]")
        self.failed = True
        raise UeCommunicationError("[HEARTBEAT] failed to reach [UE PC]")

    def _user_stop(self, signum, frame):
        # self.__del__()
        self.failed = True
        raise UeCommunicationError("User stopped execution")

    def setup_connection_with_ue_pc_server(self, host, port_dict, enable_heartbeat=True, heartbeat_message_log=False):
        """
        Method initializes connection with UePcServer machine using UTE_UE_PC class variable

        :param host:                    Host name or ip of Ue_Pc_Server
        :type host:                     string
        :param port_dict:               Dictionary containing Ue_Pc_Server ports
        :type port_dict:                dict with fields server_command_input, server_qxdm_messages,
                                        server_command_output, heartbeat
        :param enable_heartbeat:        Enables heartbeat mechanic, default - True
        :type enable_heartbeat:         bool
        :param heartbeat_message_log:   Logs heartbeat messages to Robot Log, WARNING: may cause Robot Framework html log
                                        to not be valid for creation, default - False
        :type heartbeat_message_log:    bool

        :return:                    None
        :rtype:                     None
        """
        self.ue_pc_host = host
        logger_name = 'ute_ue.ue_pc.{}'.format(self.ue_pc_host)
        self.logger = core_logging.create_logger(logger_name, 'UE_PC_{}.log'.format(self.ue_pc_host))
        self.logger.propagate = False
        self.logger.info("Active loggers: {}".format(core_logging.active_loggers))

        self.enable_heartbeat = enable_heartbeat
        self._setup_sockets(port_dict, enable_heartbeat, heartbeat_message_log)

    def _setup_sockets(self, port_dict, enable_heartbeat, heartbeat_message_log):
        try:
            server_command_input = port_dict["server_command_input"]
            server_qxdm_messages = port_dict["server_qxdm_messages"]
            server_command_output = port_dict["server_command_output"]
            server_heartbeat = port_dict["heartbeat"]
        except AttributeError:
            self.logger.warning("Unable to extract all data from UTE_UE_PC configuration.")
            raise

        self._setup_command_input(server_command_input, self.ue_pc_host)
        self._setup_qxdm_messages(server_qxdm_messages, self.ue_pc_host)
        self._setup_command_output(server_command_output, self.ue_pc_host)
        self._setup_heartbeat(enable_heartbeat, heartbeat_message_log, self.ue_pc_host, server_heartbeat, self.ue_pc_host)
        self.logger.info("Connection with PC Server '%s' established" % self.ue_pc_host)

    def _setup_heartbeat(self, enable_heartbeat, heartbeat_message_log, host, server_heartbeat, ue_pc_host):
        try:
            self._SOCKET_HEARTBEAT = Heartbeat(self.context, host, server_heartbeat, heartbeat_message_log)
            if enable_heartbeat:
                self._SOCKET_HEARTBEAT.daemon = True
                self._SOCKET_HEARTBEAT.start()
        except Exception as e:
            self.logger.warning("Error: %s %s" % (str(type(e)), str(e)))
            raise pc_server_exceptions.UePcConnectionnException(
                "Failed establishing connection to [UE_PC][HEARTBEAT] on: %s:%s" %
                (ue_pc_host, server_heartbeat))

    def _setup_command_output(self, server_command_output, ue_pc_host):
        try:
            self._SOCKET_COMMAND_OUTPUT = SOCKET(
                # socket=self._setup_router_connection_with_socket(ue_pc_host, server_command_output),
                socket=self._setup_subscriber_connection_with_socket(ue_pc_host, server_command_output),
                dictionary="COMMAND_OUTPUT")
        except Exception as e:
            self.logger.warning("Error: %s %s" % (str(type(e)), str(e)))
            raise pc_server_exceptions.UePcConnectionnException(
                "Failed establishing connection to [UE_PC][COMMAND_OUTPUT] on: %s:%s" %
                (ue_pc_host, server_command_output))

    def _setup_qxdm_messages(self, server_qxdm_messages, ue_pc_host):
        try:
            self._SOCKET_QXDM_MESSAGES = SOCKET(
                # socket=self._setup_router_connection_with_socket(ue_pc_host, server_qxdm_messages),
                socket=self._setup_subscriber_connection_with_socket(ue_pc_host, server_qxdm_messages),
                dictionary="QXDM_MESSAGES")
        except Exception as e:
            self.logger.warning("Error: %s %s" % (str(type(e)), str(e)))
            raise pc_server_exceptions.UePcConnectionnException(
                "Failed establishing connection to [UE_PC][QXDM_MESSAGES] on: %s:%s" %
                (ue_pc_host, server_qxdm_messages))

        self.special_outputs = {QXDM.GET_LOG_ITEM: self._SOCKET_QXDM_MESSAGES,
                                QXDM.GET_LOG_ITEMS: self._SOCKET_QXDM_MESSAGES}

    def _setup_command_input(self, server_command_input, ue_pc_host):
        try:
            self._SOCKET_COMMAND_INPUT = SOCKET(
                socket=self._setup_dealer_connection_with_socket(ue_pc_host, server_command_input),
                dictionary="COMMAND_IMPUT")
        except Exception as e:
            self.logger.warning("Error: %s %s" % (str(type(e)), str(e)))
            raise pc_server_exceptions.UePcConnectionnException(
                "Failed establishing connection to [UE_PC][COMMAND_INPUT] "
                "on: {}:{}".format(ue_pc_host, server_command_input))

    def send(self, command, **kwargs):
        """
        Method sends command on the COMMAND INPUT socket while expecting result from QXDM or COMMAND OUTPUT sockets.

        :param command:             Command to be executed on Pc Server
        :type command:              THROUGHPUT, QXDM, TEST
        :param kwargs:              Parameters to be sent to PC Server
        :type kwargs:               dict
        :return:
        """
        try:
            self.logger.info("Sending command '{}'".format(command))
            status, messages = self._send(command, self._SOCKET_COMMAND_INPUT,
                                          self.timeout_overwrite_dictionary.get(command, 0),
                                          self._SOCKET_QXDM_MESSAGES, self._SOCKET_COMMAND_OUTPUT,
                                          **kwargs)
            self.logger.info("Command '{}' executed on UE_PC".format(command))
            return self._process_output(command, messages, status)

        except pc_server_exceptions.TimeoutExceededException:
            self.logger.warning("Timeout exceeded, executing recovery")
            # self._send(TEST.RECOVERY, self._SOCKET_COMMAND_INPUT, recovery_mode=True)
            raise

    def _process_output(self, command, messages, status):
        output = self.special_outputs.get(command)
        if output:
            return status, messages.get(output.dictionary)
        output = messages.get(self._SOCKET_COMMAND_OUTPUT.dictionary)
        if output:
            for message in output:
                if message.get("command") == command.value:
                    return status, message.get("metadata", {})
        return status, output

    def close_connection_with_ue_pc_server(self):
        """
        Method closes all connection with UePcServer

        :return:                    None
        :rtype:                     None
        """
        self.logger.debug("Closing connection with ue pc server {}: stopping heartbeat".format(self.ue_pc_host))
        if self._SOCKET_HEARTBEAT:
            self._SOCKET_HEARTBEAT.stop()
        self.logger.debug("Closing connection with ue pc server {}: stopped heartbeat".format(self.ue_pc_host))
        # self._SOCKET_HEARTBEAT.join()
        import time
        time.sleep(2)
        self.logger.debug("Closing connection with ue pc server {}: closing sockets".format(self.ue_pc_host))
        if self._SOCKET_COMMAND_INPUT:
            self._SOCKET_COMMAND_INPUT.socket.close()
        self.logger.debug(
            "Closing connection with ue pc server {}: closed SOCKET_COMMAND_INPUT".format(self.ue_pc_host))
        if self._SOCKET_QXDM_MESSAGES:
            self._SOCKET_QXDM_MESSAGES.socket.close()
        self.logger.debug(
            "Closing connection with ue pc server {}: closed SOCKET_QXDM_MESSAGES".format(self.ue_pc_host))
        if self._SOCKET_COMMAND_OUTPUT:
            self._SOCKET_COMMAND_OUTPUT.socket.close()
        self.logger.debug(
            "Closing connection with ue pc server {}: closed SOCKET_COMMAND_OUTPUT".format(self.ue_pc_host))
        self._SOCKET_COMMAND_INPUT = None
        self._SOCKET_QXDM_MESSAGES = None
        self._SOCKET_COMMAND_OUTPUT = None
        self._SOCKET_HEARTBEAT = None
        self.logger.debug("Closing connection with ue pc server {}: clearing context".format(self.ue_pc_host))
        # self._context.term()
        self._context = None
        self.logger.debug("Closing connection with ue pc server {}: context cleared".format(self.ue_pc_host))

    def __del__(self):
        self.stop = True
        sockets_to_close = [self._SOCKET_COMMAND_INPUT, self._SOCKET_QXDM_MESSAGES, self._SOCKET_COMMAND_OUTPUT]
        for socket in sockets_to_close:
            if socket:
                socket.socket.close()
                socket = None

        if self._SOCKET_HEARTBEAT:
            self._SOCKET_HEARTBEAT.stop()
            self._SOCKET_HEARTBEAT = None

        if self._context:
            self._context.term()
            self._context = None
